public static double CalculateTotalCost(double carPrice, double clothesPrice, double bookPrice)
{
    // Calculate the combined price of clothes and book
    double combinedPrice = clothesPrice + bookPrice;

    // Check if the car price is at least twice the combined price
    if (carPrice < 2 * combinedPrice)
    {
        // Adjust the car price to meet the requirement
        carPrice = 2 * combinedPrice;
    }

    // Return the total cost of the purchase
    return carPrice + combinedPrice;
}
