import React from 'react';
import { View, StyleSheet } from 'react-native';

const ScrollViewComponent = ({ children }) => {
  const [currentSectionIndex, setCurrentSectionIndex] = React.useState(0);

  const onScroll = React.useCallback((event) => {
    const offsetY = event.nativeEvent.contentOffset.y;
    const totalHeight = event.nativeEvent.layoutMeasurement.height;
    const maxScrollY = totalHeight - event.nativeEvent.layoutMeasurement.height;

    if (offsetY > maxScrollY && currentSectionIndex < children.length - 1) {
      setCurrentSectionIndex(currentSectionIndex + 1);
