To divide an hour into 10 equal parts, you can use the following formula in Excel:

`=TIME(HOUR(A1), (MINUTE(A1) / 6), 0)`

This formula will return the start time of the first 10-minute interval within the given hour (A1). You can then drag this formula down to apply it to the remaining hours in your dataset.

In MATLAB, you can achieve the same result using the `datetime` function and the `mod` function:

```matlab
% Assuming your data is stored in a cell array called 'data'
hour = cellfun(@(x) x(1), data, 'UniformOutput', false);
minutes = cellfun(@(x) x(2), data, 'UniformOutput', false);

% Convert hours and minutes to seconds
seconds = hour * 3600 + minutes * 60;

% Calculate the start time of the first 10-minute interval
start_time = datetime(seconds, 'Format', 'hh:mm');

% Create a vector of start times for all hours
start_times = start_time + (0:9) * 600;
```

Both methods will give you a vector of start times for each 10-minute interval within your hourly dataset. You can then use these start times to perform more granular analysis on your data.

Here's a simple Go program that parses a struct in a Go source file and generates an AVRO schema from it. The generated schema is saved in a file named `struct.avsc`.

```go
package main

import (
	"fmt"
	"io/ioutil"
	"regexp"
	"strings"

	"github.com/apache/avro/avro"
)

type StructDefinition struct {
	Name   string
	Fields []FieldDefinition
}

type FieldDefinition struct {
	Name    string
	Type    string
	Default interface{}
}

func parseStruct(srcFile string, structName string) (*StructDefinition, error) {
	content, err := ioutil.ReadFile(srcFile)
	if err != nil {
		return nil, fmt.Errorf("error reading source file: %v", err)
	}

	re := regexp.MustCompile(`(?m)^type\s+` + structName + `\s+(?:struct|interface)\{`)
	matches := re.FindStringSubmatch(string(content))
	if len(matches) == 0 {
		return nil, fmt.Errorf("could not find struct definition for %s", structName)
	}

	fields := make([]FieldDefinition, 0)
	for _, field := range matches[1:] {
		fieldParts := strings.Split(field, " ")
		name := fieldParts[0]
		typeStr := fieldParts[1]
		defaultVal := ""

		if len(fieldParts) > 2 {
			defaultVal = fieldParts[2]
		}

		fields = append(fields, FieldDefinition{
			Name:    name,
			Type:    typeStr,
			Default: defaultVal,
		})
	}

	return &StructDefinition{
		Name:   structName,
		Fields: fields,
	}, nil
}

func generateAvroSchema(structDef *StructDefinition) ([]byte, error) {
	schema := avro.NewSchema()
	schema.SetName(structDef.Name

