Here's an example of how you can implement the email input field with TypeScript, React, and the Downshift library:

```typescript
import { useCombobox } from 'downshift';
import axios from 'axios';

const EmailsInputField = () => {
  const [emails, setEmails] = useState([]);
  const [selectedEmail, setSelectedEmail] = useState(null);

  const {
    isOpen,
    selectedItem,
    getMenuProps,
    getInputProps,
    getItemProps,
    highlightedIndex,
  } = useCombobox({
    items: emails,
    onSelect: (item) => setSelectedEmail(item),
  });

  const handleInputChange = (event) => {
    const prefix = event.target.value;
    searchEmails(prefix).then((newEmails) => {
      setEmails(newEmails);
    });
  };

  const searchEmails = async (prefix) => {
    try {
      const response = await axios.get(`/api/search-emails?prefix=${prefix}`);
      return response.data;
    } catch (error) {
      console.error(error);
      return [];
    }
  };

  return (
    <div {...getMenuProps()}>
      <input
        {...getInputProps({
          placeholder: 'Search emails',
          onChange: handleInputChange,
        })}
      />
      {isOpen && (
        <ul {...getListProps()}>
          {emails.map((email, index) => (
            <li
              {...getItemProps({
                key: email.id,
                index,
                style: {
                  backgroundColor: highlightedIndex === index ? '#f0f0f0' : 'white',
                },
              })}
            >
              {email.name} - {email.email}
            </li>
          ))}
        </ul>
      )}
    </div>
  );
};

export default EmailsInputField;
```

