Here's a simple TypeScript program that generates a bar chart using the Chart.js library. This program takes a user-inputted dataset and creates a bar chart based on it.

```typescript
// chart.ts
import * as Chart from 'chart.js';

interface Dataset {
  label: string;
  data: number[];
  backgroundColor: string[];
}

function generateBarChart(dataset: Dataset) {
  const ctx = document.getElementById('bar-chart')!.getContext('2d');
  const myChart = new Chart(ctx, {
    type: 'bar',
    data: {
      labels: dataset.data.map((_, index) => index),
      datasets: [
        {
          label: dataset.label,
          data: dataset.data,
          backgroundColor: dataset.backgroundColor,
        },
      ],
    },
    options: {
      scales: {
        y: {
          beginAtZero: true,
        },
      },
    },
  });
}

const dataset: Dataset = {
  label: 'Dataset 1',
  data: [10, 20, 30],
  backgroundColor: ['#FF6384', '#36A2EB', '#FFCE56'],
};

generateBarChart(dataset);
```

