To find the kth largest element in the given list, we can use the quickselect algorithm. This algorithm has a time complexity of O(n), which is efficient for large lists. Here's a Python implementation of quickselect:

```python
def quickselect(numbers, k):
    def partition(low, high):
        pivot = numbers[high]
        i = low - 1
        for j in range(low, high):
            if numbers[j] <= pivot:
                i += 1
                numbers[i], numbers[j] = numbers[j], numbers[i]
        numbers[i + 1], numbers[high] = numbers[high], numbers[i + 1]
        return i + 1

    def quickselect_helper(low, high, k):
        if low == high:
            return numbers[low]
        pivot_index = partition(low, high)
        if pivot_index == k - 1:
            return numbers[pivot_index]
        elif pivot_index > k - 1:
            return quickselect_helper(low, pivot_index - 1, k)
        else:
            return quickselect_helper(pivot_index + 1, high, k)

    return quickselect_helper(0, len(numbers) - 1, k)

input_list = [140, 52, 172, 175, 201, 159, 291, 255, 93, 10, 111, 125, 221, 149, 92, 218, 199, 205, 108, 55]
k = 19
result = quickselect(input_list, k)
print("The", k, "-th largest element in the list is:", result)
```

